/**
 * Pure parsing for the OpenRouter image API.
 *
 * `POST /api/v1/images` returns the generated bytes inline as base64 in
 * `b64_json` — there is no hosted URL field in the response — so the only
 * decisions here are which entries are usable and what file extension each
 * one's media type implies.
 */

export interface GeneratedImage {
  /** The bytes, base64-encoded, exactly as the API returned them. */
  base64: string;
  /** e.g. `image/png`, or an empty string where the provider declared none. */
  mediaType: string;
}

export interface ImageGenerationResult {
  images: GeneratedImage[];
  /** Provider-reported cost in USD, when the response carried one. */
  costUsd?: number;
}

/**
 * The formats this store can name, one table rather than two so a media type
 * and its extension cannot drift apart.
 *
 * `image/jpg` is accepted as an alias because it is not unheard of on the wire,
 * but it maps to the canonical `image/jpeg` going the other way — the first
 * entry for an extension wins, so that ordering is load-bearing.
 */
const IMAGE_FORMATS: readonly { mediaType: string; ext: string }[] = [
  { mediaType: "image/png", ext: "png" },
  { mediaType: "image/jpeg", ext: "jpg" },
  { mediaType: "image/jpg", ext: "jpg" },
  { mediaType: "image/webp", ext: "webp" },
  { mediaType: "image/svg+xml", ext: "svg" },
];

/**
 * What an image is stored as when nothing identified its format.
 *
 * `png` is the one format every image provider behind this endpoint can emit,
 * so it is the safe thing to call an unlabelled image.
 */
const FALLBACK_FORMAT = { mediaType: "image/png", ext: "png" };

/**
 * The file extension for a media type, defaulting to `png`.
 *
 * A default rather than a rejection: the API says `media_type` appears only
 * "whenever the format is identifiable", so refusing an undeclared one would
 * discard an image whose bytes we already hold.
 */
export function extensionForMediaType(mediaType: string | undefined): string {
  if (!mediaType) return FALLBACK_FORMAT.ext;
  const normalized = mediaType.toLowerCase();
  return (
    IMAGE_FORMATS.find((format) => format.mediaType === normalized)?.ext ??
    FALLBACK_FORMAT.ext
  );
}

/**
 * The media type to store an image under when the provider declared none.
 *
 * The counterpart of `extensionForMediaType`, and the reason the table is one
 * list: an object stored without a content type comes back from Garage as
 * `binary/octet-stream`, and the browser is then left to guess at bytes we know
 * the format of.
 */
export function mediaTypeForExtension(ext: string): string {
  const normalized = ext.toLowerCase();
  return (
    IMAGE_FORMATS.find((format) => format.ext === normalized)?.mediaType ??
    FALLBACK_FORMAT.mediaType
  );
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

/**
 * Parses a `POST /api/v1/images` response body.
 *
 * Returns `null` for anything that is not a usable response — a non-object, a
 * missing `data` array, or a `data` array with no usable entry — so the caller
 * reports one failure instead of rendering nothing. An entry without a
 * non-empty `b64_json` string is dropped rather than failing the response: a
 * provider that returns one image beside an unusable sibling still returned the
 * image.
 */
export function parseImageResponse(
  payload: unknown,
): ImageGenerationResult | null {
  if (!isRecord(payload)) return null;

  const data = payload.data;
  if (!Array.isArray(data)) return null;

  const images: GeneratedImage[] = [];
  for (const entry of data) {
    if (!isRecord(entry)) continue;
    const base64 = entry.b64_json;
    if (typeof base64 !== "string" || base64.length === 0) continue;
    images.push({
      base64,
      mediaType: typeof entry.media_type === "string" ? entry.media_type : "",
    });
  }

  if (images.length === 0) return null;

  const usage = payload.usage;
  const costUsd =
    isRecord(usage) && typeof usage.cost === "number" ? usage.cost : undefined;

  return { images, costUsd };
}
